template<class T>
void RebindLive(void *theBlock, unsigned int theMaxUsed, Board *theBoard)
{
    SaveArraySlot<T> *aSlots = static_cast<SaveArraySlot<T> *>(theBlock);
    for (unsigned int i = 0; i < theMaxUsed; ++i)
    {
        if ((aSlots[i].mID >> 16) == 0)
            continue;
        aSlots[i].mItem.mApp = theBoard->mApp;
        aSlots[i].mItem.mBoard = theBoard;
    }
}

void FixBoardAfterLoad(Board *theBoard)
{
    theBoard->mTangleKelpTree.clear();
    theBoard->mFlowerPotTree.clear();
    theBoard->mPumpkinTree.clear();

    PlantSlot *aPlants = theBoard->mPlants.mBlock;
    for (unsigned int i = 0; i < theBoard->mPlants.mMaxUsedCount; ++i)
    {
        if ((aPlants[i].mID >> 16) == 0)
            continue;
        Plant *aPlant = &aPlants[i].mItem;
        aPlant->mApp = theBoard->mApp;
        aPlant->mBoard = theBoard;
        if (aPlant->mSeedType == SEED_TANGLEKELP)
            theBoard->mTangleKelpTree.insert(aPlant);
        else if (aPlant->mSeedType == SEED_FLOWERPOT)
            theBoard->mFlowerPotTree.insert(aPlant);
        else if (aPlant->mSeedType == SEED_PUMPKINSHELL)
            theBoard->mPumpkinTree.insert(aPlant);
    }

    ZombieSlot *aZombies = theBoard->mZombies.mBlock;
    for (unsigned int i = 0; i < theBoard->mZombies.mMaxUsedCount; ++i)
    {
        if ((aZombies[i].mID >> 16) == 0)
            continue;
        aZombies[i].mItem.mApp = theBoard->mApp;
        aZombies[i].mItem.mBoard = theBoard;
        aZombies[i].mItem.StartZombieSound();
    }

    RebindLive<Projectile>(theBoard->mProjectiles.mBlock, theBoard->mProjectiles.mMaxUsedCount, theBoard);
    RebindLive<Coin>(theBoard->mCoins.mBlock, theBoard->mCoins.mMaxUsedCount, theBoard);
    RebindLive<LawnMower>(theBoard->mLawnMowers.mBlock, theBoard->mLawnMowers.mMaxUsedCount, theBoard);
    RebindLive<GridItem>(theBoard->mGridItems.mBlock, theBoard->mGridItems.mMaxUsedCount, theBoard);

    theBoard->mAdvice->mApp = theBoard->mApp;
    theBoard->mCursorObject[0]->mApp = theBoard->mApp;
    theBoard->mCursorObject[0]->mBoard = theBoard;
    theBoard->mCursorPreview[0]->mApp = theBoard->mApp;
    theBoard->mCursorPreview[0]->mBoard = theBoard;

    SeedBank *aSeedBank = theBoard->mSeedBank[0];
    aSeedBank->mApp = theBoard->mApp;
    aSeedBank->mBoard = theBoard;
    for (int i = 0; i < 10; ++i)
    {
        aSeedBank->mSeedPackets[i].mApp = theBoard->mApp;
        aSeedBank->mSeedPackets[i].mBoard = theBoard;
        aSeedBank->mSeedPackets[i].mSeedBank = aSeedBank;
    }

    theBoard->mChallenge->mApp = theBoard->mApp;
    theBoard->mChallenge->mBoard = theBoard;
    theBoard->mGamepadControls[0]->mGamepadIndex =
        theBoard->mApp->PlayerToGamepadIndex(theBoard->mGamepadControls[0]->mPlayerIndex);
    theBoard->mApp->mMusic->mApp = theBoard->mApp;
    theBoard->mApp->mMusic->mMusicInterface = theBoard->mApp->mMusicInterface;
}

void SyncBoard(SaveGameContext *theContext, Board *theBoard)
{
    SyncRegisteredBlocks(theContext, theBoard->mSyncBlocks);
    SyncItemArray<Zombie>(theContext, &theBoard->mZombies);
    SyncItemArray<Plant>(theContext, &theBoard->mPlants);
    SyncItemArray<Projectile>(theContext, &theBoard->mProjectiles);
    SyncItemArray<Coin>(theContext, &theBoard->mCoins);
    SyncItemArray<LawnMower>(theContext, &theBoard->mLawnMowers);
    SyncItemArray<GridItem>(theContext, &theBoard->mGridItems);

    TodParticleHolder *aParticles = theBoard->mApp->mEffectSystem->mParticleHolder;
    SyncItemArray<TodParticleSystem>(theContext, &aParticles->mParticleSystems);
    SyncItemArray<TodParticleEmitter>(theContext, &aParticles->mEmitters);
    SyncParticleItemArray(theContext, &aParticles->mParticles);

    ReanimationHolder *aReanims = theBoard->mApp->mEffectSystem->mReanimationHolder;
    SyncItemArray<Reanimation>(theContext, aReanims);
    TrailHolder *aTrails = theBoard->mApp->mEffectSystem->mTrailHolder;
    SyncItemArray<Trail>(theContext, &aTrails->mTrails);
    SyncAttachmentArray(theContext, theBoard->mApp->mEffectSystem->mAttachmentHolder);

    ParticleSystemSlot *aSystems =
        aParticles->mParticleSystems.mBlock;
    for (unsigned int i = 0; i < aParticles->mParticleSystems.mMaxUsedCount; ++i)
    {
        if ((aSystems[i].mID >> 16) != 0)
            SyncParticleSystem(theContext, theBoard, &aSystems[i].mItem);
    }

    ReanimationSlot *aReanimSlots = aReanims->mBlock;
    for (unsigned int i = 0; i < aReanims->mMaxUsedCount; ++i)
    {
        if ((aReanimSlots[i].mID >> 16) != 0)
            SyncReanimationState(theContext, theBoard, &aReanimSlots[i].mItem);
    }

    TrailSlot *aTrailSlots = aTrails->mTrails.mBlock;
    for (unsigned int i = 0; i < aTrails->mTrails.mMaxUsedCount; ++i)
    {
        if ((aTrailSlots[i].mID >> 16) == 0)
            continue;
        theContext->SyncTrailDef(aTrailSlots[i].mItem.mDefinition);
        if (theContext->mReading)
            aTrailSlots[i].mItem.mTrailHolder = aTrails;
    }

    SyncRegisteredBlocks(theContext, theBoard->mCursorObject[0]->mSyncBlocks);
    SyncRegisteredBlocks(theContext, theBoard->mCursorPreview[0]->mSyncBlocks);
    SyncRegisteredBlocks(theContext, theBoard->mAdvice->mSyncBlocks);
    SyncRegisteredBlocks(theContext, theBoard->mSeedBank[0]->mSyncBlocks);
    SyncRegisteredBlocks(theContext, theBoard->mChallenge->mSyncBlocks);
    SyncRegisteredBlocks(theContext, theBoard->mApp->mMusic->mSyncBlocks);
    SyncRegisteredBlocks(theContext, theBoard->mGamepadControls[0]->mSyncBlocks);
    theBoard->mGamepadControls[0]->Update(0.01f);

    int aMagic = kSaveMagic;
    theContext->SyncInt(aMagic);
    if (aMagic != kSaveMagic)
        theContext->mReadError = true;
}


