bool LawnSaveGame(Board *theBoard, const Sexy::String &theFileName)
{
    if (!theBoard->mApp->IsFullVersion())
        return true;

    SaveGameContext context;
    int header[] = {kSaveMagic, kSaveVersion, 0};
    context.SyncBytes(header, sizeof(header));
    SyncBoard(&context, theBoard);
    bool saved = theBoard->mApp->WriteBufferToFile(theFileName, &context);
    theBoard->mApp->mNeedGoBackToMain = false;
    return saved;
}

int LawnLoadGame(Board *theBoard, SaveGameContext *theContext)
{
    if (theBoard->mApp->IsFullVersion() == 0)
        return 1;

    struct SaveHeader
    {
        int mMagic;
        unsigned int mVersion;
        int mPad;
    };
    SaveHeader aHeader = {};
    theContext->SyncBytes(&aHeader, 12);
    if (theContext->mReadError || aHeader.mMagic != kSaveMagic || aHeader.mVersion > 8)
    {
        gLawnApp->HandleCorruptedGameFile();
        return 0;
    }
    if (aHeader.mVersion != 8)
    {
        gLawnApp->HandleOldGameFile();
        return 0;
    }

    SyncBoard(theContext, theBoard);
    if (gLawnApp->IsAdventureMode())
    {
        int aBoardLevel = theBoard->mLevel;
        int aPlayerLevel = gLawnApp->mPlayerInfo->mLevel;
        if (aBoardLevel != aPlayerLevel)
        {
            int aLevel = aBoardLevel;
            if (aPlayerLevel > aLevel)
                aLevel = aPlayerLevel;
            theBoard->mLevel = aLevel;
            gLawnApp->mPlayerInfo->mLevel = aLevel;
        }
    }
    if (theContext->mReadError)
    {
        gLawnApp->HandleCorruptedGameFile();
        return 0;
    }
    FixBoardAfterLoad(theBoard);
    theBoard->mApp->mGameScene = SCENE_PLAYING;
    return 1;
}
